case class Subject(id: String, roles: Set[String])
case class AuthedRequest[A](subject: Subject, request: Request[A]) extends WrappedRequest[A](request)

class AuthRefiner @Inject() (implicit ec: ExecutionContext)
    extends ActionRefiner[Request, AuthedRequest] {
  def refine[A](request: Request[A]): Future[Either[Result, AuthedRequest[A]]] =
    Future.successful(subjectOf(request).toRight(Results.Unauthorized).map(AuthedRequest(_, request)))
}
